44	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
45	                       std::string& err) {
46	  err.clear();
47	
48	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
49	  // `${boundary#0[xX]}`); the .symtab is never touched.
50	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
51	    std::string addr = boundary.substr(2);
52	    if (addr.empty()) {
53	      err = "malformed address '" + boundary + "'";
54	      return "";
55	    }
56	    return addr;
57	  }
58	
59	  std::vector<char> buf;
60	  if (!slurp(elf_path, buf)) {
61	    err = "cannot read ELF '" + elf_path + "'";
62	    return "";
63	  }
64	
65	  Elf64_Ehdr eh;
66	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
67	    err = "not an ELF file: " + elf_path;
68	    return "";
69	  }
70	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
71	    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
72	    return "";
73	  }
74	
75	  // Scan section headers for a symbol table; resolve names through its linked
76	  // string table (sh_link).
77	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
78	    Elf64_Shdr sym_sh;
79	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
80	      break;
81	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
82	
83	    Elf64_Shdr str_sh;
84	    if (sym_sh.sh_link >= eh.e_shnum ||
85	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
86	              str_sh))
87	      continue;
88	
89	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
90	    for (size_t s = 0; s < nsym; ++s) {
91	      Elf64_Sym sym;
92	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
93	      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only
94	
95	      const size_t noff = str_sh.sh_offset + sym.st_name;
96	      if (noff >= buf.size()) continue;
97	      const char* name = buf.data() + noff;
98	      const size_t avail = buf.size() - noff;
99	      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
100	      if (boundary == name) return to_hex(sym.st_value);
101	    }
102	  }
103	
104	  err = "symbol '" + boundary + "' not defined in " + elf_path;
105	  return "";
106	}
107	
108	uint64_t elf_entry(const std::string& elf_path, std::string& err) {
109	  err.clear();
110	  std::vector<char> buf;
111	  if (!slurp(elf_path, buf)) {
112	    err = "cannot read ELF '" + elf_path + "'";
113	    return 0;
114	  }
115	  Elf64_Ehdr eh;
116	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
117	    err = "not an ELF file: " + elf_path;
118	    return 0;
119	  }
120	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
121	    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
122	    return 0;
123	  }
124	  return eh.e_entry;
125	}
126	
127	uint64_t elf_load_top(const std::string& elf_path, std::string& err) {
128	  err.clear();
129	  std::vector<char> buf;
130	  if (!slurp(elf_path, buf)) {
131	    err = "cannot read ELF '" + elf_path + "'";
132	    return 0;
133	  }
134	  Elf64_Ehdr eh;
135	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
136	    err = "not an ELF file: " + elf_path;
137	    return 0;
138	  }
139	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
140	    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
141	    return 0;
142	  }
143	  // Top of the static image: the highest (p_paddr + p_memsz) over PT_LOAD.
144	  // p_paddr is the guest-physical placement (== p_vaddr for the identity-mapped
145	  // bare-metal fixtures), the space the V-scratch GPA also lives in.
146	  uint64_t top = 0;
147	  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
148	    Elf64_Phdr ph;
149	    const size_t off = static_cast<size_t>(eh.e_phoff) +
150	                       static_cast<size_t>(i) * eh.e_phentsize;
151	    if (!load(buf, off, ph)) {
152	      err = "truncated program header table in '" + elf_path + "'";
153	      return 0;
154	    }
155	    if (ph.p_type != PT_LOAD) continue;
156	    const uint64_t end = ph.p_paddr + ph.p_memsz;
157	    if (end > top) top = end;
158	  }
159	  return top;  // 0 (empty err) when the ELF has no loadable segments
160	}
161	
162	std::string symbolize(const std::string& elf_path, uint64_t addr) {
163	  std::vector<char> buf;
164	  if (!slurp(elf_path, buf)) return "";
165	
166	  Elf64_Ehdr eh;
167	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0 ||
168	      eh.e_ident[EI_CLASS] != ELFCLASS64)
169	    return "";
170	
171	  // Track the highest-valued FUNC symbol whose range covers addr (st_value <=
172	  // addr < st_value + st_size), falling back to the nearest preceding FUNC
173	  // when sizes are absent.
174	  std::string best_name;
175	  uint64_t best_value = 0;
176	  bool found = false;
177	
178	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
179	    Elf64_Shdr sym_sh;
180	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
181	      break;
182	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
183	
184	    Elf64_Shdr str_sh;
185	    if (sym_sh.sh_link >= eh.e_shnum ||
186	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
187	              str_sh))
188	      continue;
189	
190	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
191	    for (size_t s = 0; s < nsym; ++s) {
192	      Elf64_Sym sym;
193	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
194	      if (sym.st_shndx == SHN_UNDEF) continue;
195	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
196	      if (sym.st_value > addr) continue;
197	      // With a size, require coverage; without, accept as a preceding label.
198	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
199	      if (found && sym.st_value <= best_value) continue;
200	
201	      const size_t noff = str_sh.sh_offset + sym.st_name;
202	      if (noff >= buf.size()) continue;
203	      const char* name = buf.data() + noff;
204	      const size_t avail = buf.size() - noff;
205	      if (::strnlen(name, avail) == avail) continue;
206	
207	      best_name = name;
208	      best_value = sym.st_value;
209	      found = true;
210	    }
211	  }
212	
213	  if (!found) return "";
214	  const uint64_t off = addr - best_value;
215	  if (off == 0) return best_name;
216	  std::ostringstream ss;
217	  ss << best_name << "+0x" << std::hex << off;
218	  return ss.str();
219	}
