41	// Validate the lone-ELF positional shape the standalone models require: print
42	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
43	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
44	// spawns a --describe subprocess per Verilator build). `model` labels the error.
45	int check_one_elf(const Cli& cli, const char* model) {
46	  if (cli.positional.empty()) {
47	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
48	    return 2;
49	  }
50	  if (cli.positional.size() > 1) {
51	    std::fprintf(stderr,
52	                 "andes-sim run --model %s: unexpected argument '%s' "
53	                 "(engine args go after --)\n",
54	                 model, cli.positional[1].c_str());
55	    return 2;
56	  }
57	  return 0;
58	}
