60	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
61	// single ELF, then exec the resolved engine standalone with `extra` (model
62	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
63	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
64	// per-model differences -- which engine, and how it is selected -- are resolved
65	// by the caller; `model` here only labels the positional diagnostics.
66	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
67	                   const char* model,
68	                   const std::vector<std::string>& extra = {}) {
69	  if (int rc = check_one_elf(cli, model)) return rc;
70	  std::vector<std::string> args = extra;
71	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
72	  std::string err;
73	  int rc = run_passthrough(eng, "standalone", cli.positional[0], args, err);
74	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
75	  return rc;
76	}
