78	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
79	// only the built-in qemu descriptor, so it resolves that directly rather than
80	// discover_engines(), which would spawn a --describe subprocess per Verilator
81	// build only to discard them all here.
82	int run_fast(const Cli& cli) {
83	  // fast is QEMU-only; an explicit engine must name it.
84	  if (!cli.engine.empty() && cli.engine != "qemu") {
85	    std::fprintf(stderr,
86	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
87	                 cli.engine.c_str());
88	    return 2;
89	  }
90	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
91	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
92	  std::string err;
93	  const std::vector<std::string> mem = qemu_m_args(cli.mem_size, err);
94	  if (!err.empty()) {
95	    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
96	    return 2;
97	  }
98	  return run_standalone(cli, builtin_qemu(), "fast", mem);
99	}
