101	// Defined below run_accurate; --cosim on the cycle model dispatches to it.
102	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng);
103	
104	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
105	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
106	// engine's own output. Unlike fast, this must discover the Verilator build(s)
107	// to resolve the engine (explicit --engine, else the sole one).
108	int run_accurate(const Cli& cli) {
109	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
110	  // --describe subprocess per Verilator build only to fail on the argument.
111	  if (int rc = check_one_elf(cli, "cycle")) return rc;
112	  // --mem-size is validated but has nothing to size: the cycle engine always
113	  // models its full DRAM window. Say so instead of silently ignoring it.
114	  if (!cli.mem_size.empty()) {
115	    std::string se;
116	    if (parse_size(cli.mem_size, se); !se.empty()) {
117	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
118	                   se.c_str());
119	      return 2;
120	    }
121	    std::fprintf(stderr,
122	                 "[andes-sim] --mem-size: the cycle engine models its full "
123	                 "DRAM window; nothing to size\n");
124	  }
125	  Discovery disc = discover_engines();
126	  std::string err;
127	  const EngineDescriptor* eng =
128	      resolve_accurate_engine(disc.engines, cli.engine, err);
129	  if (!eng) {
130	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
131	    // Surface why an expected engine may be absent (failed --describe, etc.).
132	    for (const std::string& w : disc.warnings)
133	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
134	    return 2;
135	  }
136	  // --cosim on the cycle model = lock-step DV co-sim against a QEMU oracle,
137	  // not a plain standalone run.
138	  if (cli.cosim) return run_cosim_lockstep(cli, *eng);
139	  return run_standalone(cli, *eng, "cycle");
140	}
