142	// Parse --cosim-max-records: empty => 0 (unbounded; the oracle runs to program
143	// exit and defines the record count). Returns false + sets err on a bad value.
144	bool parse_cosim_max(const std::string& s, unsigned long long& out,
145	                     std::string& err) {
146	  out = 0;
147	  if (s.empty()) return true;
148	  char* end = nullptr;
149	  out = std::strtoull(s.c_str(), &end, 10);
150	  if (!end || *end != '\0') {
151	    err = "--cosim-max-records: want a non-negative integer, got '" + s + "'";
152	    return false;
153	  }
154	  return true;
155	}
