157	// `run --model cycle --cosim`: lock-step DV co-sim (cosim_redesign F6, usage
158	// 1). Two independent boots of the same ELF -- the QEMU oracle (golden) and
159	// the vsim DUT -- each drain one full record per execution attempt from the
160	// arm pc; the streams are aligned by attempt index and diffed to localize the
161	// first diverging instruction. No handoff, no shared mmap. The oracle runs
162	// first (MHz-fast, defines the record count K); the DUT is then bounded to K
163	// so a diverged hart cannot run away.
164	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng) {
165	  auto fail = [](const std::string& msg) {
166	    std::fprintf(stderr, "andes-sim run --model cycle --cosim: %s\n",
167	                 msg.c_str());
168	    return 2;
169	  };
170	  if (int rc = check_one_elf(cli, "cycle")) return rc;
171	
172	  std::error_code ec;
173	  const fs::path elf = fs::absolute(cli.positional[0], ec);
174	  if (ec || !fs::is_regular_file(elf, ec))
175	    return fail("ELF not found: " + cli.positional[0]);
176	  const std::string elf_path = elf.string();
177	
178	  // Arm pc: --pc-start (symbol or 0x addr) overrides the ELF entry default.
179	  std::string err;
180	  uint64_t arm_pc = 0;
181	  if (cli.pc_start.empty()) {
182	    arm_pc = elf_entry(elf_path, err);
183	    if (!err.empty()) return fail(err);
184	  } else {
185	    const std::string hex = resolve_pc(elf_path, cli.pc_start, err);
186	    if (!err.empty()) return fail(err);
187	    arm_pc = std::strtoull(hex.c_str(), nullptr, 16);
188	  }
189	  char arm_buf[32];
190	  std::snprintf(arm_buf, sizeof(arm_buf), "0x%llx",
191	                static_cast<unsigned long long>(arm_pc));
192	
193	  unsigned long long max_records = 0;
194	  if (!parse_cosim_max(cli.cosim_max_records, max_records, err))
195	    return fail(err);
196	
197	  // Workdir for the two record streams (removed on exit).
198	  const fs::path wd =
199	      fs::temp_directory_path() /
200	      ("andes-cosim-ls-" + std::to_string(::getpid()));
201	  fs::create_directories(wd, ec);
202	  const std::string oracle_stream = (wd / "oracle.ckpts").string();
203	  const std::string dut_stream = (wd / "dut.ckpts").string();
204	  auto cleanup = [&] { fs::remove_all(wd, ec); };
205	
206	  // Lock-step is slow on the DUT (a DMI step + full drain per attempt, tens
207	  // of attempts/s); give both legs a generous ceiling. --cosim-max-records
208	  // bounds the work; the timeout is only the runaway backstop.
209	  constexpr int kTimeoutMs = 1800 * 1000;
210	
211	  // ---- Leg 1: QEMU oracle (golden). Standalone andes machine + the
212	  // lock-step plugin; outfile IS the record stream. vlen syncs from the DUT
213	  // engine so the V-state widths match. ----
214	  const std::string plugin = [&] {
215	    if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return std::string(p);
216	    return default_plugin_path().string();
217	  }();
218	  std::string plugin_arg = plugin + ",outfile=" + oracle_stream +
219	                           ",lockstep_pc=" + arm_buf;
220	  if (max_records != 0)
221	    plugin_arg += ",lockstep_max=" + std::to_string(max_records);
222	
223	  const std::string vlen = std::to_string(synced_vlen(eng.vlen));
224	  std::vector<std::string> qemu_argv = {
225	      builtin_qemu().bin_path, "-machine", "andes_ae350", "-cpu",
226	      "andes-ax45mpv,vlen=" + vlen, "-nographic", "-semihosting-config",
227	      "enable=on,target=native", "-bios", elf_path, "-plugin", plugin_arg};
228	
229	  std::fprintf(stderr,
230	               "[andes-sim] cosim lock-step: oracle (QEMU) boots from reset, "
231	               "arms at %s\n",
232	               arm_buf);
233	  const RunResult qr = run_process(qemu_argv, kTimeoutMs);
234	  if (qr.spawn_failed) { cleanup(); return fail("oracle: failed to spawn QEMU"); }
235	  if (qr.timed_out) { cleanup(); return fail("oracle: timed out"); }
236	  if (!qr.out.empty()) std::fwrite(qr.out.data(), 1, qr.out.size(), stdout);
237	
238	  const StateStream oracle = read_state_stream(oracle_stream);
239	  if (!oracle.ok()) { cleanup(); return fail("oracle: " + oracle.error); }
240	  if (oracle.records.empty()) {
241	    cleanup();
242	    return fail("oracle produced no records (arm pc " + std::string(arm_buf) +
243	                " never reached?)");
244	  }
245	  const unsigned long long k = oracle.records.size();
246	  std::fprintf(stderr,
247	               "[andes-sim] cosim lock-step: oracle drained %llu record(s); "
248	               "DUT (vsim) bounded to the same\n",
249	               k);
250	
251	  // ---- Leg 2: vsim DUT, bounded to the oracle's K records. ----
252	  std::vector<std::string> vsim_argv = {
253	      eng.bin_path,         elf_path,
254	      "--cosim-lockstep",   "--cosim-out",
255	      dut_stream,           "--cosim-arm-pc",
256	      arm_buf,              "--cosim-max-records",
257	      std::to_string(k)};
258	  const RunResult vr = run_process(vsim_argv, kTimeoutMs);
259	  if (vr.spawn_failed) { cleanup(); return fail("DUT: failed to spawn vsim"); }
260	  if (vr.timed_out) { cleanup(); return fail("DUT: timed out"); }
261	  if (!vr.out.empty()) std::fwrite(vr.out.data(), 1, vr.out.size(), stdout);
262	
263	  const StateStream dut = read_state_stream(dut_stream);
264	  if (!dut.ok()) { cleanup(); return fail("DUT: " + dut.error); }
265	
266	  // ---- Compare ----
267	  const LockstepResult cmp = compare_lockstep_streams(oracle.records, dut.records);
268	  cleanup();
269	
270	  if (!cmp.diverged) {
271	    std::printf(
272	        "[cosim] PASS: %zu records match (lock-step, 1 attempt/record)\n",
273	        cmp.matched);
274	    return 0;
275	  }
276	
277	  if (!cmp.length_mismatch.empty()) {
278	    std::fprintf(stderr, "[cosim] FAIL: %s\n", cmp.length_mismatch.c_str());
279	    std::fprintf(stderr,
280	                 "        first divergence is a control-flow split at attempt "
281	                 "%zu (after %zu matching)\n",
282	                 cmp.record, cmp.matched);
283	    return 1;
284	  }
285	
286	  const std::string osym = symbolize(elf_path, cmp.oracle_pc);
287	  const std::string dsym = symbolize(elf_path, cmp.dut_pc);
288	  std::fprintf(stderr,
289	               "[cosim] FAIL: first divergence at attempt %zu (after %zu "
290	               "matching)\n",
291	               cmp.record, cmp.matched);
292	  std::fprintf(stderr, "        pc  vsim=0x%llx  qemu=0x%llx%s%s\n",
293	               static_cast<unsigned long long>(cmp.dut_pc),
294	               static_cast<unsigned long long>(cmp.oracle_pc),
295	               dsym.empty() ? "" : ("   (" + dsym + ")").c_str(),
296	               (!osym.empty() && osym != dsym) ? (" oracle=(" + osym + ")").c_str()
297	                                               : "");
298	  for (const FieldDiff& d : cmp.diff.diffs)
299	    std::fprintf(stderr, "        %-8s vsim=0x%llx  qemu=0x%llx\n",
300	                 d.field.c_str(), d.got, d.ref);
301	  return 1;
302	}
