304	// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
305	// handoff (no QEMU2). The trigger (marker|pc|icount) delimits the ROI; the cycle
306	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
307	// driver's tests/e2e.sh delegation with a single window-cycle line.
308	int run_hybrid(const Cli& cli) {
309	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
310	  auto fail = [](const std::string& msg) {
311	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
312	    return 2;
313	  };
314	
315	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
316	
317	  // Resolve to an absolute, existing path: a clean error beats a downstream
318	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
319	  std::error_code ec;
320	  const fs::path elf = fs::absolute(cli.positional[0], ec);
321	  if (ec || !fs::is_regular_file(elf, ec))
322	    return fail("ELF not found: " + cli.positional[0]);
323	  const std::string elf_path = elf.string();
324	
325	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
326	  // mistake fails fast without spawning a --describe per Verilator build.
327	  std::string err;
328	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
329	  if (!err.empty()) return fail(err);
330	
331	  // --verify needs a boundary the oracle can arm on; the icount window's
332	  // off-by-one semantics differ between the legs (see verify_oracle.md).
333	  if (cli.verify && trig.kind != "marker" && trig.kind != "pc")
334	    return fail("--verify supports --trigger marker|pc");
335	
336	  // --cosim needs the same entry boundary for the oracle to arm on.
337	  if (cli.cosim && trig.kind != "marker" && trig.kind != "pc")
338	    return fail("--cosim supports --trigger marker|pc");
339	  unsigned long long cosim_interval = 10000;  // default per cosim_roi.md
340	  if (cli.cosim && !cli.cosim_interval.empty()) {
341	    char* end = nullptr;
342	    cosim_interval = std::strtoull(cli.cosim_interval.c_str(), &end, 10);
343	    if (!end || *end != '\0' || cli.cosim_interval.empty() ||
344	        cosim_interval == 0)
345	      return fail("--cosim-interval: want a positive integer, got '" +
346	                  cli.cosim_interval + "'");
347	  }
348	
349	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
350	  if (!err.empty()) return fail(err);
351	
352	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
353	  if (!cli.mem_size.empty()) {
354	    std::string se;
355	    mem = parse_size(cli.mem_size, se);
356	    if (!se.empty()) return fail("--mem-size: " + se);
357	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
358	    // guest RAM here. The physical mmap reserves one V-scratch page above the
359	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
360	    // page. Failing now beats allocating a huge mmap file first and letting
361	    // QEMU die late.
362	    if (mem > max_program_mem_bytes())
363	      return fail("--mem-size " + cli.mem_size +
364	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
365	                  "reservation)");
366	  }
367	
368	  // L26/F3: refuse a run whose static image would extend into the reserved
369	  // V-transport scratch page. Scheme D parks the scratch at ram_base +
370	  // --mem-size (the mmap's extra page); a PT_LOAD segment reaching there means
371	  // the ELF was linked for more RAM than --mem-size grants, and QEMU would load
372	  // it straight onto the scratch -> silent corruption. ram_base is the fixed
373	  // andes_ae350 DRAM base (0; see L10 for the machine-base assumption). The
374	  // check is skipped when the ELF cannot be read here -- downstream reports it.
375	  {
376	    std::string e;
377	    const uint64_t top = elf_load_top(elf_path, e);
378	    const uint64_t scratch_gpa = static_cast<uint64_t>(mem);  // ram_base 0 + mem
379	    if (e.empty() && top > scratch_gpa) {
380	      char msg[256];
381	      std::snprintf(msg, sizeof(msg),
382	                    "ELF static image ends at 0x%llx, overlapping the reserved "
383	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
384	                    "; raise --mem-size or shrink the image",
385	                    static_cast<unsigned long long>(top),
386	                    static_cast<unsigned long long>(scratch_gpa));
387	      return fail(msg);
388	    }
389	  }
390	
391	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
392	  // or the sole cycle-accurate engine (reusing the F8 selector).
393	  Discovery disc = discover_engines();
394	  const EngineDescriptor* acc =
395	      resolve_accurate_engine(disc.engines, cli.engine, err);
396	  if (!acc) {
397	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", err.c_str());
398	    for (const std::string& w : disc.warnings)
399	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
400	    return 2;
401	  }
402	
403	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
404	  // cannot share architectural state with the rv64 fast leg).
405	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
406	
407	  Plan plan;
408	  plan.elf = elf_path;
409	  plan.mem_size = mem;
410	  Step qemu_step{"qemu", "fast-leg", trig};
411	  Step vsim_step{acc->id, "accurate-leg", trig};
412	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
413	  if (cli.cosim) {
414	    // Orthogonal to the trigger: the vsim leg drains a resumable checkpoint
415	    // to the <state_out>.ckpts stream every N retires (run_plan reads them
416	    // back).
417	    vsim_step.extra_args.push_back("--hybrid-cosim");
418	    vsim_step.extra_args.push_back(std::to_string(cosim_interval));
419	  }
420	  plan.steps = {qemu_step, vsim_step};
421	
422	  // Banner to stderr so the window-cycle result stands alone on stdout.
423	  // vlen is the synced value the fast leg inherits from the engine.
424	  std::fprintf(stderr,
425	               "[andes-sim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
426	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
427	               elf.stem().string().c_str());
428	
429	  const PlanResult r = run_plan(plan, disc.engines);
430	  if (!r.ok()) {
431	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", r.error.c_str());
432	    return 1;
433	  }
434	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
435	  // output, then anything the ROI wrote on vsim) belong to the user.
436	  for (const PhaseResult& p : r.phases)
437	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
438	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
439	  // vsim mcycle delta. Suppressed under --cosim: every checkpoint adds a DMI
440	  // halt + drain + resume to the vsim leg, so the delta no longer measures
441	  // the kernel (a --cosim run answers "where diverged", not "how many cycles").
442	  if (!cli.cosim) {
443	    const unsigned long long q_mc = r.phases[0].mcycle;
444	    const unsigned long long v_mc = r.phases[1].mcycle;
445	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
446	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
447	  }
448	
449	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
450	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
451	  // halt pc, and diff the two drains in-process. The oracle plan gets its
452	  // own fresh mmap: reusing the main run's would boot the oracle on the
453	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
454	  // output was already relayed from the main run.
455	  if (cli.verify) {
456	    char pcbuf[32];
457	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
458	                  static_cast<unsigned long long>(r.phases[1].st.pc));
459	    Trigger vtrig;
460	    vtrig.kind = "verify-" + trig.kind;
461	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
462	    vtrig.params["drain_pc"] = pcbuf;
463	
464	    Plan vplan;
465	    vplan.elf = elf_path;
466	    vplan.mem_size = mem;
467	    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};
468	
469	    std::fprintf(stderr,
470	                 "[andes-sim] verify: oracle leg (pure QEMU drains at the ROI "
471	                 "exit, pc=%s)\n",
472	                 pcbuf);
473	    const PlanResult vr = run_plan(vplan, disc.engines);
474	    if (!vr.ok()) {
475	      std::fprintf(stderr, "andes-sim run --verify: %s\n", vr.error.c_str());
476	      return 1;
477	    }
478	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
479	    print_diff_report(d);
480	    if (!d.ok()) {
481	      std::fprintf(stderr,
482	                   "andes-sim run --verify: vsim drain diverges from the "
483	                   "QEMU oracle\n");
484	      return 1;
485	    }
486	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
487	  }
488	
489	  // --cosim (cosim_roi F4, default off, dev): re-run the ELF on pure QEMU
490	  // with the plugin draining at the vsim checkpoints' retire deltas, then
491	  // diff checkpoint k against checkpoint k and the final drains. minstret is
492	  // restored from the entry state on resume, so `checkpoint.minstret -
493	  // entry.minstret` is the exact post-entry retire count -- both engines
494	  // sample the SAME architectural points, and the first mismatching window
495	  // brackets the divergence. Fresh mmap for the oracle (clean memory);
496	  // stdout dropped (already relayed from the main run).
497	  //
498	  // --cosim-refine (cosim_redesign F7): when set, after the coarse window is
499	  // found the driver re-runs QEMU1->vsim with explicit targets subdividing it
500	  // ~16x per pass (the vsim leg finishes at the last target, so each pass is
501	  // bounded), re-running the oracle at the vsim leg's achieved deltas, until
502	  // the window shrinks to the halt slack. QEMU1 is deterministic, so each pass
503	  // re-derives the same entry state -- no mmap snapshot needed.
504	  if (cli.cosim) {
505	    const unsigned long long m0 = r.phases[0].st.minstret;
506	
507	    // Flatten a leg's checkpoints + final drain into (state, absolute-delta)
508	    // lists. False on a zero/non-ascending delta (a corrupt leg).
509	    auto collect = [&](const PhaseResult& leg,
510	                       std::vector<hybrid_state_v1>& states,
511	                       std::vector<unsigned long long>& deltas) -> bool {
512	      states.clear();
513	      deltas.clear();
514	      for (const hybrid_state_v1& c : leg.checkpoints) {
515	        const unsigned long long d = c.minstret - m0;
516	        if (d == 0 || (!deltas.empty() && d <= deltas.back())) return false;
517	        states.push_back(c);
518	        deltas.push_back(d);
519	      }
520	      const unsigned long long df = leg.st.minstret - m0;
521	      if (df == 0 || (!deltas.empty() && df <= deltas.back())) return false;
522	      states.push_back(leg.st);
523	      deltas.push_back(df);
524	      return true;
525	    };
526	
527	    auto join = [](const auto& xs) {
528	      std::string s;
529	      for (size_t i = 0; i < xs.size(); ++i)
530	        s += (i ? ":" : "") + std::to_string(xs[i]);
531	      return s;
532	    };
533	
534	    // Oracle: pure QEMU draining at the given absolute deltas. Returns its
535	    // states (checkpoints + final, length == counts.size()) or nullopt.
536	    auto run_oracle = [&](const std::vector<unsigned long long>& counts)
537	        -> std::optional<std::vector<hybrid_state_v1>> {
538	      Trigger ot;
539	      ot.kind = "cosim-" + trig.kind;
540	      if (trig.kind == "pc") ot.params["enter_pc"] = trig.params.at("enter_pc");
541	      ot.params["counts"] = join(counts);
542	      Plan op;
543	      op.elf = elf_path;
544	      op.mem_size = mem;
545	      op.steps = {Step{"qemu", "fast-leg", ot}};
546	      const PlanResult orr = run_plan(op, disc.engines);
547	      if (!orr.ok()) {
548	        std::fprintf(stderr, "andes-sim run --cosim: %s\n", orr.error.c_str());
549	        return std::nullopt;
550	      }
551	      std::vector<hybrid_state_v1> os = orr.phases[0].checkpoints;
552	      os.push_back(orr.phases[0].st);
553	      if (os.size() != counts.size()) {
554	        std::fprintf(stderr,
555	                     "andes-sim run --cosim: oracle returned %zu states, "
556	                     "want %zu\n",
557	                     os.size(), counts.size());
558	        return std::nullopt;
559	      }
560	      return os;
561	    };
562	
563	    // First index where two aligned state lists differ (trap cause excluded:
564	    // the hybrid ROI is trap-free by contract).
565	    auto first_div = [](const std::vector<hybrid_state_v1>& os,
566	                        const std::vector<hybrid_state_v1>& vs)
567	        -> std::optional<size_t> {
568	      for (size_t i = 0; i < os.size() && i < vs.size(); ++i)
569	        if (!diff_states(os[i], vs[i]).ok()) return i;
570	      return std::nullopt;
571	    };
572	
573	    // ---- pass 1: the interval checkpoints from the main hybrid run ----
574	    std::vector<hybrid_state_v1> vstates;
575	    std::vector<unsigned long long> vdeltas;
576	    if (!collect(r.phases[1], vstates, vdeltas)) {
577	      std::fprintf(stderr,
578	                   "andes-sim run --cosim: non-ascending vsim checkpoint "
579	                   "deltas (corrupt leg?)\n");
580	      return 1;
581	    }
582	    std::fprintf(stderr,
583	                 "[andes-sim] cosim: oracle leg (pure QEMU, %zu sample(s))\n",
584	                 vdeltas.size());
585	    const auto ostates = run_oracle(vdeltas);
586	    if (!ostates) return 1;
587	
588	    auto div = first_div(*ostates, vstates);
589	    if (!div) {
590	      std::printf("[cosim] PASS: %zu checkpoint(s) + final state match the "
591	                  "QEMU oracle (interval %llu, %llu ROI retires)\n",
592	                  vstates.size() - 1, cosim_interval, vdeltas.back());
593	      std::printf("PASS: --model hybrid --trigger %s (%s)\n",
594	                  trig.kind.c_str(), elf.stem().string().c_str());
595	      return 0;
596	    }
597	
598	    // Coarse diverging window (lo, hi]; div_v/div_o are the states at hi.
599	    unsigned long long lo = (*div == 0) ? 0 : vdeltas[*div - 1];
600	    unsigned long long hi = vdeltas[*div];
601	    hybrid_state_v1 div_v = vstates[*div];
602	    hybrid_state_v1 div_o = (*ostates)[*div];
603	    DiffReport div_diff = diff_states(div_o, div_v);
604	
605	    // ---- refine: subdivide (lo, hi] until it reaches the halt-slack floor.
606	    // Targets must stay >= kSpacing apart so the vsim halt overshoot cannot
607	    // reorder the achieved deltas; below that the haltreq checkpoint cannot
608	    // resolve further (use --model cycle --cosim for exact single-stepping).
609	    if (cli.cosim_refine) {
610	      constexpr unsigned long long kSpacing = 8;
611	      constexpr int kFanout = 16;
612	      int pass = 1;
613	      while (hi - lo > kSpacing) {
614	        const std::vector<uint64_t> targets =
615	            subdivide_window(lo, hi, kFanout, kSpacing);
616	        if (targets.size() < 2) break;
617	        std::fprintf(stderr,
618	                     "[andes-sim] cosim-refine pass %d: window (%llu, %llu], "
619	                     "%zu probes\n",
620	                     ++pass, lo, hi, targets.size());
621	
622	        Step q{"qemu", "fast-leg", trig};
623	        Step v{acc->id, "accurate-leg", trig};
624	        v.extra_args = {"--hybrid-cosim-at", join(targets)};
625	        Plan p;
626	        p.elf = elf_path;
627	        p.mem_size = mem;
628	        p.steps = {q, v};
629	        const PlanResult pr = run_plan(p, disc.engines);
630	        if (!pr.ok()) {
631	          std::fprintf(stderr, "andes-sim run --cosim-refine: %s\n",
632	                       pr.error.c_str());
633	          return 1;
634	        }
635	        std::vector<hybrid_state_v1> rv;
636	        std::vector<unsigned long long> rd;
637	        if (!collect(pr.phases[1], rv, rd)) {
638	          std::fprintf(stderr,
639	                       "andes-sim run --cosim-refine: non-ascending vsim "
640	                       "deltas (halt slack exceeded the probe spacing?)\n");
641	          break;  // report the best window found so far
642	        }
643	        const auto ro = run_oracle(rd);
644	        if (!ro) return 1;
645	        const auto rdiv = first_div(*ro, rv);
646	        if (!rdiv) break;  // no narrower split resolved; keep current window
647	
648	        const unsigned long long nlo = (*rdiv == 0) ? lo : rd[*rdiv - 1];
649	        const unsigned long long nhi = rd[*rdiv];
650	        if (nhi >= hi && nlo <= lo) break;  // no progress
651	        lo = nlo;
652	        hi = nhi;
653	        div_v = rv[*rdiv];
654	        div_o = (*ro)[*rdiv];
655	        div_diff = diff_states(div_o, div_v);
656	      }
657	    }
658	
659	    // ---- report the (narrowed) diverging window ----
660	    print_diff_report(div_diff);
661	    const std::string sym = symbolize(elf_path, div_v.pc);
662	    std::fprintf(stderr,
663	                 "[cosim] FAIL: divergence in retires %llu..%llu after entry "
664	                 "(%llu insn window)%s\n",
665	                 lo, hi, hi - lo, cli.cosim_refine ? ", narrowed" : "");
666	    std::fprintf(stderr, "        at retire ~%llu: pc vsim=0x%llx qemu=0x%llx%s\n",
667	                 hi, static_cast<unsigned long long>(div_v.pc),
668	                 static_cast<unsigned long long>(div_o.pc),
669	                 sym.empty() ? "" : ("   (" + sym + ")").c_str());
670	    if (cli.cosim_refine && hi - lo > 8)
671	      std::fprintf(stderr,
672	                   "        (window at the halt-slack floor; for the exact "
673	                   "instruction use --model cycle --cosim on a reset testbench)\n");
674	    return 1;
675	  }
676	
677	  std::printf("PASS: --model hybrid --trigger %s (%s)\n", trig.kind.c_str(),
678	              elf.stem().string().c_str());
679	  return 0;
680	}
