684	int cmd_run(const Cli& cli) {
685	  if (cli.model.empty()) {
686	    std::fprintf(stderr,
687	                 "andes-sim run: --model fast|cycle|hybrid is required\n");
688	    return 2;
689	  }
690	  if (!find_model(cli.model)) {
691	    std::fprintf(stderr,
692	                 "andes-sim run: unknown model '%s' (want fast|cycle|hybrid)\n",
693	                 cli.model.c_str());
694	    return 2;
695	  }
696	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
697	  // composition has a second engine to check.
698	  if (cli.verify && cli.model != "hybrid") {
699	    std::fprintf(stderr,
700	                 "andes-sim run: --verify requires --model hybrid (the %s "
701	                 "model has nothing to cross-check)\n",
702	                 cli.model.c_str());
703	    return 2;
704	  }
705	  // --cosim cross-checks against a QEMU oracle: hybrid (ROI window checkpoints)
706	  // or cycle (lock-step from reset). The fast model is QEMU itself -- nothing
707	  // to check.
708	  if (cli.cosim && cli.model == "fast") {
709	    std::fprintf(stderr,
710	                 "andes-sim run: --cosim requires --model hybrid or cycle "
711	                 "(fast is QEMU itself, nothing to cross-check)\n");
712	    return 2;
713	  }
714	  if (cli.cosim && cli.verify) {
715	    std::fprintf(stderr,
716	                 "andes-sim run: --verify and --cosim are exclusive (--cosim "
717	                 "already cross-checks the final state)\n");
718	    return 2;
719	  }
720	  // --cosim-interval is the hybrid ROI knob; --cosim-max-records is the
721	  // cycle lock-step knob. Each requires --cosim and its own model.
722	  if (!cli.cosim && !cli.cosim_interval.empty()) {
723	    std::fprintf(stderr, "andes-sim run: --cosim-interval requires --cosim\n");
724	    return 2;
725	  }
726	  if (!cli.cosim_interval.empty() && cli.model != "hybrid") {
727	    std::fprintf(stderr,
728	                 "andes-sim run: --cosim-interval applies to --model hybrid "
729	                 "(cycle lock-step uses --cosim-max-records)\n");
730	    return 2;
731	  }
732	  if (!cli.cosim_max_records.empty() && !(cli.cosim && cli.model == "cycle")) {
733	    std::fprintf(stderr,
734	                 "andes-sim run: --cosim-max-records requires --model cycle "
735	                 "--cosim (lock-step)\n");
736	    return 2;
737	  }
738	  // --cosim-refine narrows the hybrid ROI window; it has no meaning for the
739	  // cycle lock-step (already exact) or without --cosim.
740	  if (cli.cosim_refine && !(cli.cosim && cli.model == "hybrid")) {
741	    std::fprintf(stderr,
742	                 "andes-sim run: --cosim-refine requires --model hybrid "
743	                 "--cosim (cycle lock-step is already instruction-exact)\n");
744	    return 2;
745	  }
746	  if (cli.model == "fast") return run_fast(cli);
747	  if (cli.model == "cycle") return run_accurate(cli);
748	  return run_hybrid(cli);  // model validated above; only hybrid remains
749	}
