363	  // Record sink: V-merge from scratch RAM (same as the exit drain), then
364	  // append the record to the `path` stream. The stream is truncated here
365	  // so a re-run never carries stale records.
366	  auto make_stream_sink(const std::string& path)
367	    -> std::function<void(const hybrid_state_v1&, uint64_t)>
368	  {
369	    std::ofstream{path, std::ios::binary | std::ios::trunc};
370	    return [this, path](const hybrid_state_v1& drained, uint64_t k) {
371	      auto state = drained;
372	      if ((state.flags & HYBRID_FLAG_V) != 0u) {
373	        hybrid::read_v_from_scratch(
374	          state,
375	          std::span<const uint8_t>{platform.main_memory.data.data(),
376	                                   platform.main_memory.data.size()});
377	      }
378	      spdlog::info("hybrid cosim: record {} at pc=0x{:x}, appending to {}",
379	                   k, state.pc, path);
380	      std::ofstream f(path, std::ios::binary | std::ios::app);
381	      f.write(reinterpret_cast<const char*>(&state), sizeof(state));
382	    };
383	  }
