614	  auto check_hybrid_handoff() -> std::optional<int>
615	  {
616	    if constexpr (!requires { cpu.get_committed_pc(); }) {
617	      return std::nullopt;
618	    } else {
619	      const auto committed = cpu.get_committed_pc();
620	      if (committed.empty()) return std::nullopt;
621	      for (const auto pc: committed[0]) {
622	        auto state = std::optional<hybrid_state_v1>{};
623	        if (hybrid_handoff_)
624	          state = hybrid_handoff_->on_retire(pc);
625	        else if (hybrid_icount_handoff_)
626	          state = hybrid_icount_handoff_->on_retire(pc);
627	        if (state) {
628	          // V-register merge: the fixture's vsim-phase epilogue is expected
629	          // to have run vse8.v v0..v31 to scratch RAM before the exit
630	          // trigger fired. Read those bytes back into state.vreg[] so the
631	          // drained handoff state carries vsim's actual V values, not
632	          // QEMU 1's stale snapshot.
633	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
634	            hybrid::read_v_from_scratch(
635	              *state,
636	              std::span<const uint8_t>{platform.main_memory.data.data(),
637	                                       platform.main_memory.data.size()});
638	          }
639	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
640	                       pc, hybrid_state_path_);
641	          std::ofstream f(hybrid_state_path_, std::ios::binary);
642	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
643	          return hybrid::kExitHandoffToQemu;
644	        }
645	      }
646	      return std::nullopt;
647	    }
648	  }
